def occurance_substring(text: str, substring: str):
    """
    Find the occurrence and position of a substring within a string.

    Parameters:
        text (str): The main string to search in.
        substring (str): The substring to find.

    Returns:
        tuple or None: A tuple containing the substring, start index, and end index if found; otherwise, None.
    """
    if not text or not substring:
        return None

    start = text.find(substring)

    if start != -1:
        end = start + len(substring)
        return (substring, start, end)
    else:
        return None

# Test cases based on the provided assert
assert occurance_substring('python programming, python language', 'python') == ('python', 0, 6)

def check_occurences(tuples_list):
    """
    Takes a list of tuples and returns a dictionary mapping each unique tuple 
    to the number of times it occurs in the list.

    Parameters:
    tuples_list (list): A list of tuples.

    Returns:
    dict: A dictionary where keys are the unique tuples from the input list 
          and values are the counts of those tuples.
    """
    count_dict = {}
    for item in tuples_list:
        if item in count_dict:
            count_dict[item] += 1
        else:
            count_dict[item] = 1
    return count_dict

# Verification with the provided assert statement
assert check_occurences([(3, 1), (1, 3), (2, 5), (5, 2), (6, 3)]) == {(1, 3): 2, (2, 5): 2, (3, 6): 1}

def sequential_search(arr, element):
    """
    Searches for an element in a list sequentially.

    Parameters:
    arr (list): The list to search within.
    element: The element to search for.

    Returns:
    tuple: A boolean indicating if the element is found and its index (or -1 if not found).
    """
    try:
        index = arr.index(element)
        return (True, index)
    except ValueError:
        return (False, -1)

# Verification based on the provided assert statement
assert sequential_search([11,23,58,31,56,77,43,12,65,19], 31) == (True, 3)

def frequency_lists(data):
    """
    Counts the frequency of each element in a flattened list of lists.

    Parameters:
        data (list of list): A list containing multiple inner lists.

    Returns:
        dict: A dictionary where keys are elements from the input lists and values are their counts.
    """
    freq = {}
    for sublist in data:
        for element in sublist:
            if element in freq:
                freq[element] += 1
            else:
                freq[element] = 1
    return freq

# Verification with the provided assert
assert frequency_lists([[1, 2, 3, 2], [4, 5, 6, 2], [7, 8, 9, 5]]) == {1: 1, 2: 3, 3: 1, 4: 1, 5: 2, 6: 1, 7: 1, 8: 1, 9: 1}
